<?php declare(strict_types=1); ?>
<h1><?= e($page['h1']) ?></h1><div class="intro" data-intro><?php foreach ($page['intro'] as $p): ?><p><?= e($p) ?></p><?php endforeach ?></div>
<?php if (!empty($page['discovery'])): ?><nav aria-label="Opciones de esta lista"><ul class="chips"><?php foreach ($page['discovery'] as $section): ?><li><a href="#<?= e($section['id']) ?>"><?= e($section['h']) ?></a></li><?php endforeach ?></ul></nav><?php endif ?>
<?php list_links($page['route']); ?>
<?php $promoShown=false; $showNames=static function(array $items) use (&$promoShown): void { cards(array_slice($items,0,12)); if (!$promoShown) { app_block();$promoShown=true; } if (count($items)>12) cards(array_slice($items,12)); }; ?>
<?php if (!empty($page['splitGender'])): $groups=[]; foreach (['f'=>['id'=>'nombres-para-ninas','label'=>'Nombres para niñas'],'m'=>['id'=>'nombres-para-ninos','label'=>'Nombres para niños y varones'],'u'=>['id'=>'nombres-unisex','label'=>'Nombres unisex']] as $gender=>$group) { $group['items']=array_values(array_filter($page['items'],static fn($n)=>$n['gender']===$gender));if ($group['items']) $groups[]=$group; } ?>
<p class="sub"><?= count($page['items']) ?> nombres para explorar. Dentro de cada grupo, el orden es alfabético. Tocá el corazón para guardar favoritos.</p><nav aria-label="Ver nombres por categoría"><ul class="chips"><?php foreach ($groups as $group): ?><li><a href="#<?= e($group['id']) ?>"><?= e($group['label']) ?></a></li><?php endforeach ?></ul></nav>
<?php foreach ($groups as $group): ?><section aria-labelledby="<?= e($group['id']) ?>"><h2 id="<?= e($group['id']) ?>"><?= e($group['label']) ?><?= isset($page['letter'])?' con '.e(strtoupper($page['letter'])):'' ?></h2><?php $showNames($group['items']); ?></section><?php endforeach ?>
<?php else: ?><h2><?= count($page['items']) ?> nombres para explorar</h2><p class="sub">Tocá el corazón para armar tu lista. El orden es alfabético.</p><?php $showNames($page['items']); endif ?>
<p><a class="btn" href="/elegir/">Afiná la búsqueda</a><a class="btn btn-ghost" href="/mi-lista/">Ver mis favoritos</a></p>
<?php foreach ($page['discovery']??[] as $section): ?><section aria-labelledby="<?= e($section['id']) ?>"><h2 id="<?= e($section['id']) ?>"><?= e($section['h']) ?></h2><?php foreach ($section['p'] as $paragraph): ?><p><?= e($paragraph) ?></p><?php endforeach ?><?php if (!empty($section['names'])): ?><ul class="chips"><?php foreach ($section['names'] as $slug): ?><li><a href="<?= e(name_url($bySlug[$slug])) ?>"><?= e($bySlug[$slug]['name']) ?>: significado y origen</a></li><?php endforeach ?></ul><?php endif ?><?php if (!empty($section['links'])): ?><nav aria-label="Seguí explorando <?= e($section['h']) ?>"><ul class="chips"><?php foreach ($section['links'] as $link): ?><li><a href="<?= e($link['route']) ?>"><?= e($link['label']) ?></a></li><?php endforeach ?></ul></nav><?php endif ?></section><?php endforeach ?>
